<script setup>
import {uid} from "./id";
import {ref,computed,watch,toRaw,nextTick} from 'vue';
import {useRoute,useRouter} from 'vue-router';
import {Droplets,LayoutGrid,BookOpen,FlaskConical,History,Settings,Plus,Search,ArrowUpRight,ArrowLeft,Check,Download,Upload,X,Trash2,Star,Undo2,Leaf,Menu} from 'lucide-vue-next';
import {useLab,KEY,validate} from './store';import {calculate} from './calc';
const lab=useLab(),route=useRoute(),router=useRouter();
const nav=[['/','My flavours',LayoutGrid],['/recipes','Recipes',BookOpen],['/mix','Mixing desk',FlaskConical],['/history','Batch history',History]];
const query=ref(''),filter=ref('all'),sort=ref('name'),brand=ref('all'),toast=ref(''),modal=ref(null),editor=ref(null),comment=ref(''),confirmBatch=ref(false),pendingImport=ref(null),dialog=ref(null);let opener;
const clone=x=>JSON.parse(JSON.stringify(x));
const fmt=n=>Number(n.toFixed(2)).toLocaleString('en-GB');
const date=d=>new Date(d).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'});
const tell=s=>{toast.value=s;setTimeout(()=>toast.value='',5000)};
const run=async fn=>{try{await fn()}catch(e){tell(e.message)}};
const email=ref(''),password=ref(''),authBusy=ref(false);
async function authenticate(signup=false){authBusy.value=true;try{tell(await lab.authenticate(email.value,password.value,signup));password.value='';}catch(e){tell(e.message);}finally{authBusy.value=false;}}
lab.init().catch(e=>tell(e.message));
const flavours=computed(()=>lab.data.flavours);
const low=computed(()=>flavours.value.filter(f=>f.amount>0&&f.amount<=5).length);
const empty=computed(()=>flavours.value.filter(f=>f.amount===0).length);
const brands=computed(()=>[...new Set(flavours.value.map(f=>f.company))].sort());
const filtered=computed(()=>flavours.value.filter(f=>(f.name+' '+f.company).toLowerCase().includes(query.value.toLowerCase())&&(brand.value==='all'||f.company===brand.value)&&(filter.value==='all'||filter.value==='low'&&f.amount>0&&f.amount<=5||filter.value==='empty'&&f.amount===0||filter.value==='rated'&&f.rating>=4)).sort((a,b)=>sort.value==='stock'?a.amount-b.amount:sort.value==='rating'?b.rating-a.rating:a.name.localeCompare(b.name)));
const total=computed(()=>flavours.value.reduce((s,f)=>s+f.amount,0));
const blankRecipe=()=>({id:uid(),name:'',volume:100,vg:70,nicotine:0,strength:18,nicPg:100,ingredients:[{flavourId:'',percent:1}],rating:0,comments:[],notes:''});
const recipe=ref(blankRecipe());
const result=computed(()=>calculate(recipe.value,flavours.value));
const percentage=computed(()=>recipe.value.ingredients.reduce((s,i)=>s+(Number(i.percent)||0),0));
function open(kind,item){opener=document.activeElement;modal.value=kind;comment.value='';editor.value=item?clone(item):{id:uid(),name:'',company:'',amount:0,emoji:'🧪',pg:100,rating:0,comments:[],notes:''};nextTick(()=>dialog.value?.showModal());}
function close(){dialog.value?.close();modal.value=null;editor.value=null;opener?.focus();}
function trap(e){if(e.key==='Escape'){e.preventDefault();close();}}
function saveFlavour(){run(async()=>{const f=editor.value;if(!f.name.trim()||!f.company.trim()||!Number.isFinite(f.amount)||f.amount<0||!Number.isFinite(f.pg)||f.pg<0||f.pg>100)throw Error('Enter a name, manufacturer, valid stock and PG percentage.');await lab.save('flavours',clone(f));close();tell('Flavour saved.');});}
function addComment(){if(!comment.value.trim())return;editor.value.comments.push({id:uid(),text:comment.value.trim(),date:new Date().toISOString()});comment.value='';}
function loadRecipe(r){recipe.value=clone(r);router.push('/mix');}
function newRecipe(){recipe.value=blankRecipe();router.push('/mix');}
function saveRecipe(){run(async()=>{if(!recipe.value.name.trim())throw Error('Give your recipe a name.');if(result.value.errors.length)throw Error(result.value.errors[0]);await lab.save('recipes',clone(recipe.value));tell('Recipe saved.');});}
function mix(){run(async()=>{if(!recipe.value.name.trim())throw Error('Give your recipe a name.');await lab.mix(clone(recipe.value));confirmBatch.value=false;tell('Batch recorded. Flavour stock updated.');router.push('/history');});}
function exportData(raw=false){const data=raw?localStorage.getItem(KEY):JSON.stringify(lab.data,null,2);const url=URL.createObjectURL(new Blob([data||''],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`flavour-lab-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function importFile(e){const file=e.target.files[0];if(!file)return;try{pendingImport.value=validate(JSON.parse(await file.text()));}catch(err){tell('Import failed: '+err.message);}e.target.value='';}
function reviewSave(){run(async()=>{await lab.save('recipes',clone(editor.value));if(recipe.value.id===editor.value.id)recipe.value=clone(editor.value);close();tell('Recipe notes saved.');});}
watch(()=>lab.user?.id,()=>{close();recipe.value=blankRecipe();pendingImport.value=null;confirmBatch.value=false;password.value='';});
watch(()=>route.path,()=>{confirmBatch.value=false;query.value='';});
window.addEventListener('storage',e=>{if(e.key===KEY&&!lab.configured){lab.blocked=true;lab.notice='Data changed in another tab. Reload this page before editing.';}});
</script>

<template>
<div class="app-shell">
 <aside class="sidebar">
  <RouterLink to="/" class="brand"><span class="brand-mark"><Droplets :size="25"/></span><span>flavour<span class="brand-light">lab</span><small>YOUR PERSONAL MIXING SPACE</small></span></RouterLink>
  <div class="nav-label">WORKSPACE</div>
  <nav><RouterLink v-for="[path,label,icon] in nav" :key="path" :to="path" :class="{active:route.path===path}"><component :is="icon" :size="20"/><span>{{label}}</span><span v-if="path==='/'" class="nav-count">{{flavours.length}}</span></RouterLink></nav>
  <div class="sidebar-bottom"><div class="local-note"><span class="status-dot"></span><strong>A little space of your own</strong><p>{{lab.configured?(lab.user?'Private cloud collection':'Sign in to your collection'):'Stored on this device'}}.<br>Your flavours, your creations.</p></div><RouterLink to="/settings" class="settings-link"><Settings :size="19"/>Settings & backups</RouterLink><div class="profile"><span>L</span><div>My workspace<small>Personal collection</small></div></div></div>
 </aside>
 <main>
  <header class="topbar"><span>My workspace <span class="slash">/</span> {{route.path==='/'?'Flavour library':route.path==='/mix'?'Mixing desk':route.path==='/recipes'?'Recipe collection':route.path==='/history'?'Batch history':'Settings'}}</span><RouterLink to="/settings" class="saved"><span class="status-dot"></span>Settings & backups</RouterLink></header>
  <div v-if="lab.busy" class="alert mx-page" role="status">Saving or loading your cloud collection…</div>
  <div v-if="lab.notice" class="alert mx-page">{{lab.notice}} <RouterLink to="/settings">Open Settings</RouterLink> <button @click="exportData(true)">Export original device data</button></div>
  <div class="page">
   <template v-if="route.path==='/'">
    <section class="page-heading"><div><div class="eyebrow">A COLLECTION OF POSSIBILITIES</div><h1>My flavours<span class="mint-dot">.</span></h1><p>A home for every flavour. A little inspiration for your next mix.</p></div><button class="primary" @click="open('flavour')"><Plus :size="18"/>Add flavour</button></section>
    <section class="stats-grid"><div class="stat mint"><span class="stat-icon"><Droplets/></span><div><small>Flavours in your collection</small><strong>{{flavours.length}} <span>flavours</span></strong></div><Leaf class="stat-decoration"/></div><div class="stat lilac"><span class="stat-icon"><FlaskConical/></span><div><small>A whole lot of possibility</small><strong>{{fmt(total)}} <span>ml in stock</span></strong></div></div><button class="stat peach text-left" @click="filter=filter==='low'?'all':'low'"><span class="stat-icon"><span>↘</span></span><div><small>Time for a little top-up</small><strong>{{low}} <span>running low</span></strong></div><ArrowUpRight :size="20"/></button></section>
    <section class="collection-panel"><div class="panel-top"><h2>Your collection <span class="pill">{{flavours.length}}</span></h2><div class="search"><Search :size="18"/><input v-model="query" aria-label="Search flavours" placeholder="Find a flavour or brand…"/></div></div>
    <div class="filter-row"><div class="tabs"><button v-for="[id,label] in [['all','All flavours'],['low','Running low'],['empty','Out of stock'],['rated','Top rated']]" :class="{selected:filter===id}" @click="filter=id">{{label}}<span v-if="id==='empty'">{{empty}}</span></button></div><div class="selects"><select v-model="brand" aria-label="Filter by manufacturer"><option value="all">All brands</option><option v-for="b in brands">{{b}}</option></select><select v-model="sort" aria-label="Sort flavours"><option value="name">Name: A–Z</option><option value="stock">Stock: low first</option><option value="rating">Highest rated</option></select></div></div>
    <div class="flavour-grid"><button v-for="(f,i) in filtered" :key="f.id" class="flavour-card" @click="open('flavour',f)"><div class="card-top"><div class="flavour-art" :class="['art-'+(Number(f.id.slice(1))%5||0)]">{{f.emoji||'🧪'}}</div><span v-if="f.amount===0" class="stock-label out">Out of stock</span><span v-else-if="f.amount<=5" class="stock-label low">Running low</span><span v-else class="stock-label">In stock</span></div><small class="manufacturer">{{f.company}}</small><h3>{{f.name}}</h3><div class="rating-display"><span :class="{rated:f.rating}">{{f.rating?'★'.repeat(f.rating)+'☆'.repeat(5-f.rating):'☆☆☆☆☆'}}</span><small>{{f.rating?f.rating+'/5':'Not rated'}}</small></div><div class="stock-bottom"><span><strong>{{fmt(f.amount)}}</strong> ml left</span><ArrowUpRight :size="17"/></div><div class="stock-track"><i :style="{width:Math.min(f.amount/30*100,100)+'%'}" :class="{low:f.amount<=5}"/></div></button></div>
    <div v-if="!filtered.length" class="empty-state"><Search/><h3>No flavours found</h3><p>Try another search or filter.</p><button @click="query='';filter='all';brand='all'">Clear filters</button></div><div class="panel-foot">Showing {{filtered.length}} of {{flavours.length}} flavours <span>Good things start with a little experimentation.</span></div></section>
   </template>
   <template v-else-if="route.path==='/recipes'">
    <section class="page-heading"><div><div class="eyebrow">IDEAS WORTH KEEPING</div><h1>Your recipe book<span class="mint-dot">.</span></h1><p>Fine-tune a favourite, or dream up something new.</p></div><button class="primary" @click="newRecipe"><Plus :size="18"/>Create recipe</button></section>
    <div v-if="!lab.data.recipes.length" class="empty-state big-empty"><span class="empty-art">🧪</span><h2>Your next favourite starts here</h2><p>Create a recipe using your collection. Save it, add tasting notes,<br>and mix a batch when you're ready.</p><button class="primary" @click="newRecipe">Create your first recipe <ArrowUpRight :size="18"/></button></div>
    <div class="recipe-grid"><article v-for="r in lab.data.recipes" class="recipe-card"><div class="recipe-art">{{r.ingredients.map(i=>flavours.find(f=>f.id===i.flavourId)?.emoji||'🧪').slice(0,3).join(' ')}}</div><div class="p-6"><small class="eyebrow">{{r.ingredients.length}} INGREDIENTS · {{r.vg}} VG / {{100-r.vg}} PG</small><h2>{{r.name}}</h2><p>{{r.notes||'A fresh idea, ready to make your own.'}}</p><div class="rating-display"><span>{{'★'.repeat(r.rating)+'☆'.repeat(5-r.rating)}}</span></div><div class="flex gap-3 mt-6"><button class="primary" @click="loadRecipe(r)">Open recipe</button><button @click="open('review',r)">Notes & rating</button></div></div></article></div>
   </template>
   <template v-else-if="route.path==='/mix'">
    <section class="page-heading"><div><div class="eyebrow">A LITTLE SCIENCE. A LITTLE CREATIVITY.</div><h1>The mixing desk<span class="mint-dot">.</span></h1><p>Build your recipe. Check your stock. Make something yours.</p></div><button @click="newRecipe"><Plus :size="18"/>New recipe</button></section>
    <div class="mix-layout"><section class="white-panel"><div class="section-number">01 <h2>The basics</h2></div><label>Recipe name<input v-model="recipe.name" placeholder="Give your creation a name"/></label><div class="field-grid"><label>Batch size (ml)<input v-model.number="recipe.volume" type="number" min="1" step="any"/></label><label>Target VG (%)<input v-model.number="recipe.vg" type="number" min="0" max="100"/></label><label>Target nicotine (mg/ml)<input v-model.number="recipe.nicotine" type="number" min="0" step="any"/></label><label>Nicotine base (mg/ml)<input v-model.number="recipe.strength" type="number" min="0.1" step="any"/></label><label>Nicotine base PG (%)<input v-model.number="recipe.nicPg" type="number" min="0" max="100"/></label><div class="field-note">{{recipe.vg}}% VG / {{100-recipe.vg}}% PG<br><small>Flavour carrier is set on each flavour.</small></div></div>
     <div class="section-number mt-8">02 <h2>Your flavour blend</h2><span class="ml-auto pill">{{fmt(percentage)}}%</span></div><div v-for="(line,i) in recipe.ingredients" :key="i" class="ingredient-row"><label>Flavour<select v-model="line.flavourId"><option value="">Choose a flavour</option><option v-for="f in flavours" :value="f.id">{{f.name}} · {{f.company}}</option></select></label><label>%<input v-model.number="line.percent" type="number" min="0.01" max="100" step="any"/></label><button class="icon-button" :aria-label="'Remove ingredient '+(i+1)" @click="recipe.ingredients.splice(i,1)"><Trash2 :size="17"/></button></div><button class="dashed w-full" @click="recipe.ingredients.push({flavourId:'',percent:1})"><Plus :size="17"/>Add ingredient</button><label class="mt-6">Recipe notes<textarea v-model="recipe.notes" rows="3" placeholder="Steep time, inspiration, tweaks for next time…"/></label><button class="primary mt-5" :disabled="lab.busy||lab.blocked" @click="saveRecipe"><BookOpen :size="17"/>Save recipe</button>
    </section><aside class="mix-summary"><div class="eyebrow">YOUR BATCH, AT A GLANCE</div><h2>{{fmt(Number(recipe.volume)||0)}} <span>ml</span></h2><p>{{recipe.name||'An idea in the making'}}</p><div class="summary-lines"><div v-for="r in result.rows"><span>{{r.name}}<small v-if="r.ml>r.available" class="shortage">Short by {{fmt(r.ml-r.available)}} ml</small></span><strong>{{fmt(r.ml)}} ml</strong></div><div><span>Nicotine base</span><strong>{{fmt(result.nic)}} ml</strong></div><div><span>PG</span><strong>{{fmt(result.pg)}} ml</strong></div><div><span>VG</span><strong>{{fmt(result.vg)}} ml</strong></div></div><p v-for="error in result.errors" class="error-text">{{error}}</p><div v-if="!result.errors.length&&!result.shortages.length" class="stock-ok"><Check :size="17"/>Your flavours are ready to go</div><p v-if="result.shortages.length" class="error-text">Not enough flavour stock for this batch.</p><button class="primary w-full" :disabled="!recipe.name.trim()||!!result.errors.length||!!result.shortages.length" @click="confirmBatch=true"><FlaskConical :size="18"/>Make this batch</button><div v-if="confirmBatch" class="confirm-box"><strong>Record this batch?</strong><p>This deducts the listed flavour amounts. PG, VG and nicotine stock are not tracked.</p><div class="flex gap-2"><button class="primary" :disabled="lab.busy||lab.blocked" @click="mix">Confirm mix</button><button @click="confirmBatch=false">Cancel</button></div></div><small class="summary-foot">Stock changes only after confirmation.<br>You can undo a batch in your history.</small></aside></div>
   </template>
   <template v-else-if="route.path==='/history'">
    <section class="page-heading"><div><div class="eyebrow">FROM IDEA TO BOTTLE</div><h1>Batch history<span class="mint-dot">.</span></h1><p>A record of what you've made, and exactly what went into it.</p></div></section><div v-if="!lab.data.batches.length" class="empty-state big-empty"><History :size="40"/><h2>A fresh page in your mixing story</h2><p>Your confirmed batches will appear here.</p><button class="primary" @click="router.push('/mix')">Go to mixing desk</button></div><article v-for="b in lab.data.batches" class="batch white-panel"><div class="flex justify-between gap-4 flex-wrap"><div><small class="eyebrow">{{date(b.date)}}</small><h2>{{b.name}}</h2><p>{{fmt(b.volume)}} ml · {{b.undone?'Undone, stock restored':'Mixed and deducted'}}</p></div><button :disabled="b.undone||lab.busy||lab.blocked" @click="run(async()=>{await lab.undo(b.id);tell('Batch undone. Flavour stock restored.');})"><Undo2 :size="17"/>{{b.undone?'Restored':'Undo batch'}}</button></div><details><summary>View ingredients</summary><div v-for="r in b.rows" class="history-line"><span>{{r.name}}</span><strong>{{fmt(r.ml)}} ml</strong></div></details></article>
   </template>
   <template v-else>
    <section class="page-heading"><div><div class="eyebrow">KEEP YOUR COLLECTION CLOSE</div><h1>Settings & backups<span class="mint-dot">.</span></h1><p>A little housekeeping for your personal mixing space.</p></div></section><section class="white-panel settings-panel"><h2>Cloud account</h2>
<p v-if="!lab.configured">Supabase is not connected yet. Your existing collection still works on this device. Cloud sign-in will appear once the project has been configured.</p>
<template v-else-if="lab.user"><p>Signed in as <strong>{{lab.user.email}}</strong>. Flavours, recipes, ratings, comments and batch history are saved privately to your account.</p><p>Refresh to load changes made on another device. An internet connection is required to load or change your cloud collection.</p><div class="flex gap-3 flex-wrap"><button :disabled="lab.busy" @click="run(()=>lab.refresh())">Refresh cloud collection</button><button :disabled="lab.busy" @click="run(()=>lab.signOut())">Sign out</button><button :disabled="lab.busy||lab.blocked" @click="run(()=>{pendingImport=lab.localBackup()})">Import original device collection</button></div></template>
<form v-else class="cloud-auth" @submit.prevent="authenticate(false)"><p>Sign in on each device to use the same collection. Your original device data stays untouched until you choose to import it.</p><label>Email<input v-model="email" type="email" autocomplete="email" required/></label><label>Password<input v-model="password" type="password" autocomplete="current-password" minlength="8" required/></label><div class="flex gap-3 flex-wrap mt-6"><button class="primary" :disabled="authBusy">Sign in</button><button type="button" :disabled="authBusy||!email||password.length<8" @click="authenticate(true)">Create account</button></div></form>
<hr/><h2>Your backups</h2><p>{{lab.configured?'Export a copy of your currently loaded cloud collection. Importing a backup replaces the collection for this account on every device.':'Your collection is stored in this browser. Clearing browser data removes it, so export a backup regularly.'}}</p><div class="flex gap-3 flex-wrap mt-6"><button class="primary" @click="exportData()"><Download :size="18"/>Export backup</button><label class="button upload-label"><Upload :size="18"/>Import backup<input type="file" accept=".json,application/json" @change="importFile"/></label></div><div v-if="pendingImport" class="confirm-box"><h3>Replace the current collection?</h3><p>This backup contains {{pendingImport.flavours.length}} flavours, {{pendingImport.recipes.length}} recipes and {{pendingImport.batches.length}} batches. Export your current collection first if you want to keep it.</p><div class="flex gap-3"><button class="primary" :disabled="lab.busy||(lab.configured&&lab.blocked)" @click="run(async()=>{await lab.restore(pendingImport);pendingImport=null;tell('Backup restored.');})">Replace with backup</button><button @click="pendingImport=null">Cancel</button></div></div><hr/><h2>Made for your home screen</h2><p>On a supported browser, choose 'Install app' or 'Add to Home screen'. The app shell can open offline. Cloud collections need an internet connection; device-only collections can still be edited offline. Installation requires HTTPS or localhost.</p><hr/><h2>Starting inventory</h2><p>Start by adding flavours or importing your personal backup above. New flavours default to a 100% PG carrier. Check the manufacturer information and edit this before relying on the PG/VG calculation.</p><p>Stock is measured in ml. Low stock means more than 0 and at most 5 ml. PG, VG and nicotine are calculated but not inventoried.</p></section>
   </template>
  </div><footer>flavourlab <span>A little more organised. A lot more possibility.</span></footer>
 </main>
 <dialog ref="dialog" @cancel.prevent="close" @keydown="trap" @click="e=>{if(e.target===dialog)close();}"><form v-if="editor" @submit.prevent="modal==='flavour'?saveFlavour():reviewSave()"><div class="modal-heading"><div><small class="eyebrow">{{modal==='flavour'?'YOUR COLLECTION':'TASTING NOTEBOOK'}}</small><h2>{{modal==='flavour'?'Flavour details':editor.name}}</h2></div><button type="button" class="icon-button" @click="close" aria-label="Close"><X/></button></div><template v-if="modal==='flavour'"><div class="field-grid"><label>Flavour name<input v-model="editor.name" required/></label><label>Manufacturer<input v-model="editor.company" required list="brands"/><datalist id="brands"><option v-for="b in brands">{{b}}</option></datalist></label><label>Stock remaining (ml)<input v-model.number="editor.amount" type="number" min="0" step="any" required/></label><label>Carrier PG (%)<input v-model.number="editor.pg" type="number" min="0" max="100" required/></label></div><label>Flavour icon<select v-model="editor.emoji"><option v-for="e in ['🧪','🍏','🫐','🌵','🥭','🍈','🌸','🍬','🥝','🍋','🍓','🥥','🍊','❄️']">{{e}}</option></select></label></template><label class="mt-5">Your rating</label><div class="stars"><button v-for="i in 5" type="button" @click="editor.rating=editor.rating===i?0:i" :aria-label="'Rate '+i+' out of 5'" :aria-pressed="editor.rating===i"><Star :size="27" :fill="i<=editor.rating?'#c19143':'none'" :stroke="i<=editor.rating?'#c19143':'#a4aaa6'"/></button><small>{{editor.rating||'Not rated'}}{{editor.rating?' / 5':''}}</small></div><label class="mt-5">Notes<textarea v-model="editor.notes" rows="3" placeholder="What makes this one special?"/></label><h3 class="mt-6">Comments</h3><div class="comments"><article v-for="(c,i) in editor.comments"><div><small>{{date(c.date)}}</small><button type="button" class="icon-button" aria-label="Delete comment" @click="editor.comments.splice(i,1)"><X :size="15"/></button></div><p>{{c.text}}</p></article><p v-if="!editor.comments.length" class="muted">No comments yet. Keep your tasting notes here.</p></div><div class="flex gap-2"><input v-model="comment" aria-label="New comment" placeholder="Add a tasting note…" @keydown.enter.prevent="addComment"/><button type="button" @click="addComment">Add</button></div><div class="modal-actions"><button type="button" @click="close">Cancel</button><button class="primary" :disabled="lab.busy||lab.blocked" type="submit">Save changes</button></div></form></dialog>
 <div v-if="toast" class="toast" role="status"><Check :size="18"/>{{toast}}</div>
</div>
</template>
